package net.nuggetmc.tplus.compat.bukkit.event.inventory;
import net.nuggetmc.tplus.compat.bukkit.event.*; import net.nuggetmc.tplus.compat.bukkit.entity.HumanEntity; import net.nuggetmc.tplus.compat.bukkit.inventory.*;
public class InventoryClickEvent extends Event implements Cancellable { private final InventoryView view; private final HumanEntity who; private final Inventory clicked; private final ItemStack cursor; private final int raw; private final ClickType click; private boolean cancelled; public InventoryClickEvent(HumanEntity who,InventoryView view,Inventory clicked,int raw,ItemStack cursor,ClickType click){this.who=who;this.view=view;this.clicked=clicked;this.raw=raw;this.cursor=cursor;this.click=click;} public InventoryView getView(){return view;} public HumanEntity getWhoClicked(){return who;} public Inventory getClickedInventory(){return clicked;} public int getRawSlot(){return raw;} public ItemStack getCursor(){return cursor;} public ClickType getClick(){return click;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean v){cancelled=v;} }
